.eon8-live-page .uag-blocks-common-selector {z-index:var(--z-index-desktop) !important}
@media(max-width: 976px) {.eon8-live-page .uag-blocks-common-selector {z-index:var(--z-index-tablet) !important}}
@media(max-width: 767px) {.eon8-live-page .uag-blocks-common-selector {z-index:var(--z-index-mobile) !important}}
.eon8-live-page .uk-navbar-left img {
    height: 60px;
    width: auto;
    object-fit: contain;
    transition: height 0.35s ease;
    display: block;
    margin-top:-10px;
}
.eon8-live-page .uk-navbar {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    position: relative;
    z-index: 1;
}
.eon8-live-page .uk-navbar-left {
    display: flex !important;
    align-items: center;
    flex-direction: row;
    gap: 80px !important;
    flex-wrap: nowrap;
}
.eon8-live-page .uk-navbar-right {
    display: flex !important;
    align-items: center;
    margin-left: auto;
}
.eon8-live-page .uk-navbar-nav > li > .uk-navbar-dropdown {
    left: 50% !important;
    transform: translateX(-50%) !important;
    right: auto !important;
}
.eon8-live-page .uk-navbar-nav {
    display: flex !important;
    align-items: center;
    flex-direction: row;
    gap: 5px;
    list-style: none;
    margin: 0;
    padding: 0;
}
.eon8-live-page .uk-navbar-nav > li {
    display: flex;
    align-items: center;
    position: relative;
    white-space: nowrap;
}
.eon8-live-page .uk-navbar-nav > li > a {
    display: flex;
    align-items: center;
    padding: 6px 10px;
    font-size: 14px;
    line-height: 1;
    text-decoration: none;
    position: relative;
}
.eon8-live-page .uk-navbar-nav > li > a::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 10px;
    right: 10px;
    height: 2px;
    transform: scaleX(0);
    transition: transform 0.3s ease;
    transform-origin: left;
}
.eon8-live-page .uk-navbar-nav > li > a:hover::after {
    transform: scaleX(1);
}
@media (max-width: 1024px) {.eon8-live-page .uk-navbar-left img {
        height: 50px;
    }
.eon8-live-page .uk-navbar-nav {
        gap: 5px;
    }}
@media (max-width: 768px) {.eon8-live-page .uk-navbar-left img {
        height: 45px;
    }
.eon8-live-page .uk-navbar-nav {
        display: none !important;
    }}
@media (max-width: 480px) {.eon8-live-page .uk-navbar-left img {
        height: 38px;
    }}
.eon8-live-page #responsive-form {
    max-width: 80%;
    margin: 0 auto;
    width: 100%;
    padding: 20px;
    border: 1px solid #25125247;
    border-radius: 7px;
    background: url("/wp-content/uploads/2022/01/form-bg-1.png");
    background-position: right bottom;
    background-size: cover;
    background-repeat: no-repeat;
    box-shadow: 0 0 10px #251252;
}
.eon8-live-page section.banner_inr:before {
    background-image: linear-gradient(to right bottom, #f5822000, #ff637c00, #e273c700, #8990ea00, #009fda00);
}
.eon8-live-page .ba_inr_cnt h1, .eon8-live-page .ba_inr_cnt p {
    color: #fff;
}
.eon8-live-page .wcms_desc li:before {
    height: 40px;
    line-height: 40px;
    content: "\f25a";
    transform: rotate(90deg);
}
.eon8-live-page .our_serv_sem .wcms_desc li {
    height: 40px;
    background: #fff;
}
.eon8-live-page .serv_main img {
    height: auto;
    border-radius: 2px;
    width: auto;
}
.eon8-live-page .our_serv_row {
    border: none;
}
.eon8-live-page .our_serv_row:after {
    margin-top: 0;
    padding-top: 0;
    border: none;
}
.eon8-live-page .main-timeline:after {
    content: '';
    display: block;
    clear: both;
}
.eon8-live-page .main-timeline .timeline {
    width: 80%;
    padding: 0 0 0 50px;
    margin: 0 0 30px;
    float: left;
}
.eon8-live-page .main-timeline .timeline-content {
    background-color: #fff;
    border-radius: 30px;
    display: block;
    position: relative;
}
.eon8-live-page .main-timeline .timeline-content:hover { text-decoration: none; }
.eon8-live-page .main-timeline .timeline-content:before {
    content: '';
    background: linear-gradient(45deg,#009fda,#009fda);
    height: 120px;
    width: 120px;
    border-radius: 50% 0 50% 50%;
    transform: translateY(-50%) rotate(45deg);
    position: absolute;
    left: -40px;
    top: 50%;
    bottom: -10px;
    z-index: 1;
}
.eon8-live-page .main-timeline .timeline-icon {
    color: #fff;
    background: linear-gradient(105deg,#009fda,#009fda);
    font-size: 45px;
    text-align: center;
    line-height: 100px;
    height: 100px;
    width: 100px;
    border-radius: 50%;
    box-shadow: 0 0 0 8px #fff inset, 0 0 5px #333;
    transform: translateY(-50%);
    position: absolute;
    top: 50%;
    left: -30px;
    z-index: 1;
}
.eon8-live-page .main-timeline .inner-content {
    background-color: #f5f5f5;
    padding: 15px 30px 15px 130px;
    border-radius: 30px;
}
.eon8-live-page .main-timeline .title {
    color: #009fda;
    font-size: 20px;
    font-weight: 700;
    letter-spacing: 1px;
    margin: 0 0 10px;
}
.eon8-live-page .main-timeline .description {
    letter-spacing: 1px;
    margin: 0;
}
.eon8-live-page .main-timeline .timeline:nth-child(even) {
    padding: 0 50px 0 0;
    margin: 0 0 30px;
    float: right;
}
.eon8-live-page .main-timeline .timeline:nth-child(even) .timeline-content:before {
    transform: translateY(-50%) rotate(225deg);
    left: auto;
    right: -40px;
}
.eon8-live-page .main-timeline .timeline:nth-child(even) .timeline-icon {
    left: auto;
    right: -30px;
}
.eon8-live-page .main-timeline .timeline:nth-child(even) .inner-content { padding: 15px 130px 15px 30px; }
.eon8-live-page .main-timeline .timeline:nth-child(even) .timeline-content:before { background: linear-gradient(45deg,#f58220,#f58220); }
.eon8-live-page .main-timeline .timeline:nth-child(even) .timeline-icon { background: linear-gradient(105deg,#f58220,#f58220); }
.eon8-live-page .main-timeline .timeline:nth-child(even) .title { color: #f58220; }
.eon8-live-page .main-timeline .timeline:nth-child(4n+3) .timeline-content:before { background: linear-gradient(45deg,#009fda,#009fda); }
.eon8-live-page .main-timeline .timeline:nth-child(4n+3) .timeline-icon { background: linear-gradient(105deg,#009fda,#009fda); }
.eon8-live-page .main-timeline .timeline:nth-child(4n+3) .title { color: #009fda; }
@media screen and (max-width:767px) {.eon8-live-page .main-timeline .timeline, .eon8-live-page .main-timeline .timeline:nth-child(even) {
        width: 100%;
        padding: 60px 0 0 0;
        float: none;
    }
.eon8-live-page .main-timeline .timeline-icon, .eon8-live-page .main-timeline .timeline:nth-child(even) .timeline-icon {
        transform: translateY(0) translateX(-50%);
        left: 50%;
        top: -40px;
    }
.eon8-live-page .main-timeline .timeline-content:before, .eon8-live-page .main-timeline .timeline:nth-child(even) .timeline-content:before {
        transform: translateY(0) translateX(-50%) rotate(135deg);
        left: 50%;
        top: -50px;
    }
.eon8-live-page .main-timeline .inner-content, .eon8-live-page .main-timeline .timeline:nth-child(even) .inner-content {
        text-align: center;
        padding: 115px 20px 20px;
    }}
@media screen and (max-width:567px) {.eon8-live-page .main-timeline .title { font-size: 18px; }}
.eon8-live-page .whychoose_inr .col-md-7 {
    margin-top: 0;
}
.eon8-live-page .perfect-item {
    margin-bottom: 0;
}
.eon8-live-page .perfect-item h4 {
